// Client sends:
{ "jsonrpc": "2.0", "id": 7, "method": "tools/list", "params": {} }

// Server replies:
{
  "jsonrpc": "2.0",
  "id": 7,
  "result": {
    "tools": [ { "name": "get_weather", "description": "Look up current weather" } ]
  }
}

// Request, expects a reply
{ "jsonrpc": "2.0", "id": 12, "method": "resources/read", "params": { "uri": "file:///report.txt" } }

// Notification, no reply expected
{ "jsonrpc": "2.0", "method": "notifications/resources/updated", "params": { "uri": "file:///report.txt" } }

{
  "jsonrpc": "2.0",
  "id": 9,
  "error": {
    "code": -32602,
    "message": "Invalid params",
    "data": { "missing": ["path"], "hint": "The read_file tool requires a path argument" }
  }
}

// 1. Client builds a request
{ "jsonrpc": "2.0", "id": 4, "method": "tools/call",
  "params": { "name": "get_current_time", "arguments": { "timezone": "UTC" } } }

// 2. Server executes the tool and replies
{ "jsonrpc": "2.0", "id": 4,
  "result": { "content": [ { "type": "text", "text": "2026-07-07T09:15:00Z" } ] } }
